package br.com.anderflow.metrys.offline;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
/** Histórico local com gravação atômica e limites simétricos de leitura/gravação. */
public final class HistoricoLocal{
 public static final class Mensagem{public final String papel;public String texto;public Mensagem(String p,String t){papel=p;texto=t;}}
 public static final class Conversa{public final String id;public String titulo;final List<Mensagem> mensagens=new ArrayList<>();Conversa(String i,String t){id=i;titulo=t;}}
 private static final int MAGIC=0x4d545259,MAX=4*1024*1024;
 private final File arquivo;private final LinkedHashMap<String,Conversa> dados=new LinkedHashMap<>();
 public HistoricoLocal(File pasta)throws IOException{if(!pasta.isDirectory()&&!pasta.mkdirs())throw new IOException("Não foi possível abrir o histórico.");arquivo=new File(pasta,"historico.bin");if(arquivo.isFile())ler();}
 public synchronized String nova()throws IOException{String id=UUID.randomUUID().toString();dados.put(id,new Conversa(id,"Nova conversa"));try{salvar();}catch(IOException e){dados.remove(id);throw e;}return id;}
 public synchronized List<Conversa> conversas(){List<Conversa> r=new ArrayList<>();for(Conversa c:dados.values())r.add(new Conversa(c.id,c.titulo));Collections.reverse(r);return r;}
 public synchronized List<Mensagem> mensagens(String id){List<Mensagem> r=new ArrayList<>();for(Mensagem m:obter(id).mensagens)r.add(new Mensagem(m.papel,m.texto));return r;}
 public synchronized void adicionar(String id,String p,String t)throws IOException{validar(p,t);Conversa c=obter(id);String velho=c.titulo;if(c.mensagens.isEmpty()&&p.equals("user")){String s=t.replaceAll("\\s+"," ").trim();c.titulo=s.substring(0,Math.min(52,s.length()));}c.mensagens.add(new Mensagem(p,t));try{salvar();}catch(IOException e){c.mensagens.remove(c.mensagens.size()-1);c.titulo=velho;throw e;}}
 public synchronized void atualizarUltima(String id,String p,String t)throws IOException{validar(p,t);Conversa c=obter(id);if(c.mensagens.isEmpty()||!c.mensagens.get(c.mensagens.size()-1).papel.equals(p)){adicionar(id,p,t);return;}Mensagem m=c.mensagens.get(c.mensagens.size()-1);String antes=m.texto;m.texto=t;try{salvar();}catch(IOException e){m.texto=antes;throw e;}}
 private Conversa obter(String id){Conversa c=dados.get(id);if(c==null)throw new IllegalArgumentException("Conversa não encontrada.");return c;}
 private static void validar(String p,String t){if(!"user".equals(p)&&!"assistant".equals(p))throw new IllegalArgumentException("Papel inválido.");if(t==null||t.getBytes(StandardCharsets.UTF_8).length>MAX)throw new IllegalArgumentException("Mensagem grande demais para armazenar.");}
 private static String texto(DataInputStream e)throws IOException{int n=e.readInt();if(n<0||n>MAX)throw new IOException("Texto inválido no histórico.");byte[] b=new byte[n];e.readFully(b);return new String(b,StandardCharsets.UTF_8);}
 private static void escrever(DataOutputStream s,String t)throws IOException{byte[] b=t.getBytes(StandardCharsets.UTF_8);s.writeInt(b.length);s.write(b);}
 private void ler()throws IOException{if(arquivo.length()>128L*1024*1024)throw new IOException("Histórico excede 128 MB; arquivo preservado.");try(DataInputStream e=new DataInputStream(new BufferedInputStream(new FileInputStream(arquivo)))){if(e.readInt()!=MAGIC||e.readInt()!=1)throw new IOException("Formato de histórico desconhecido.");int n=e.readInt();if(n<0||n>10000)throw new IOException("Número de conversas inválido.");for(int i=0;i<n;i++){String id=texto(e),titulo=texto(e);if(dados.containsKey(id))throw new IOException("Conversa duplicada.");Conversa c=new Conversa(id,titulo);int m=e.readInt();if(m<0||m>100000)throw new IOException("Número de mensagens inválido.");for(int j=0;j<m;j++){String p=texto(e),t=texto(e);try{validar(p,t);}catch(IllegalArgumentException ex){throw new IOException("Papel inválido no histórico.",ex);}c.mensagens.add(new Mensagem(p,t));}dados.put(id,c);}if(e.read()!=-1)throw new IOException("Dados adicionais no histórico.");}catch(EOFException e){throw new IOException("Histórico incompleto; o arquivo foi preservado.",e);}}
 private void salvar()throws IOException{
  if(dados.size()>10000)throw new IOException("Limite de 10.000 conversas atingido. Exporte uma cópia.");long tamanho=12;
  for(Conversa c:dados.values()){if(c.mensagens.size()>100000)throw new IOException("Esta conversa atingiu o limite de mensagens.");tamanho+=12L+c.id.getBytes(StandardCharsets.UTF_8).length+c.titulo.getBytes(StandardCharsets.UTF_8).length;for(Mensagem m:c.mensagens)tamanho+=8L+m.papel.getBytes(StandardCharsets.UTF_8).length+m.texto.getBytes(StandardCharsets.UTF_8).length;if(tamanho>128L*1024*1024)throw new IOException("Limite de 128 MB no histórico atingido. Exporte uma cópia.");}
  File tmp=new File(arquivo.getParentFile(),"historico.bin.tmp");try(FileOutputStream f=new FileOutputStream(tmp);DataOutputStream s=new DataOutputStream(new BufferedOutputStream(f))){s.writeInt(MAGIC);s.writeInt(1);s.writeInt(dados.size());for(Conversa c:dados.values()){escrever(s,c.id);escrever(s,c.titulo);s.writeInt(c.mensagens.size());for(Mensagem m:c.mensagens){escrever(s,m.papel);escrever(s,m.texto);}}s.flush();f.getFD().sync();}
  try{Files.move(tmp.toPath(),arquivo.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp.toPath(),arquivo.toPath(),StandardCopyOption.REPLACE_EXISTING);}
 }
}
